// Paywall (v3). Networking/auth/state live in the offscreen document; this is a
// proxy that renders the modal here and talks to the offscreen server via the
// port router installed in the service worker.
const paywall = new PaywallUI({
    paywallId: "377",
    apiOrigin: "https://platform.fastica.dev",
    auth: true,
});

/**
 * Gate a download behind the paywall. Returns true if the download may proceed.
 *
 * - granted via subscription / outside monetization scope → allow silently.
 * - granted via active trial → consume one trial action (silent, no modal) and allow.
 * - blocked (trial exhausted, no subscription) → show the paywall and only allow
 *   once the user completes a purchase; closing it without buying aborts.
 *
 * Fails open: a paywall error never blocks a download.
 */
async function passPaywall(): Promise<boolean> {
    let access: PaywallAccessResult;
    try {
        access = await paywall.getAccess();
    } catch (e) {
        new_sentry_scope().captureException(e, { data: { context: 'passPaywall-getAccess' } });
        console.error("Paywall getAccess failed, allowing download", e);
        return true;
    }

    if (access.access === 'blocked') {
        return await new Promise<boolean>((resolve) => {
            const offPurchase = paywall.on('purchase_completed', () => { cleanup(); resolve(true); });
            const offClose = paywall.on('close', () => { cleanup(); resolve(false); });
            // Capture paywall errors for observability. The modal stays interactive
            // with a retry/error state, so the terminal signal is still 'close'.
            const offError = paywall.on('error', (err) => {
                new_sentry_scope().captureException(err, { data: { context: 'passPaywall-open' } });
            });
            function cleanup() { offPurchase(); offClose(); offError(); }
            try {
                paywall.open();
            } catch (e) {
                // open() failed to even mount the modal — no 'close' will ever fire.
                // Don't hang the download: report and treat as dismissed.
                new_sentry_scope().captureException(e, { data: { context: 'passPaywall-open-throw' } });
                cleanup();
                resolve(false);
            }
        });
    }

    if (access.reason === 'trial_blocked') {
        // Consume one trial action by opening (and self-closing) the modal. Guard
        // like the blocked branch: a failed open() must not block the download.
        try {
            paywall.open();
        } catch (e) {
            new_sentry_scope().captureException(e, { data: { context: 'passPaywall-trial-open' } });
        }
    }

    return true;
}

// Guards against re-entrant downloads while the paywall gate is awaiting the
// user. Until passPaywall() resolves the Download button stays enabled, so a
// second click would otherwise open a second paywall and start a second download.
let paywallGatePending = false;

