// --- Onboarding logic ---

async function shouldShowOnboarding(): Promise<boolean> {
    if (DEBUG_DISABLE_ONBOARDING) return false;
    if (DEBUG_ALWAYS_SHOW_ONBOARDING) return true;

    // Check if user has already completed onboarding
    const { [ONBOARDING_COMPLETED_KEY]: completed } = await chrome.storage.local.get([ONBOARDING_COMPLETED_KEY]);
    if (completed === true) return false;

    // Check if user is new (has installDate) and if onboarding should be shown (50% chance)
    const { installDate, showOnboarding } = await chrome.storage.sync.get(['installDate', 'showOnboarding']);

    // Don't show if user was randomly assigned to not see onboarding
    if (showOnboarding === false) return false;

    // Only show onboarding to new users (installDate is set for new users)
    // Old users won't have installDate, so they won't see onboarding
    return !!installDate;
}

function initializeOnboarding() {
    const modal = document.getElementById('onboardingModal') as HTMLElement | null;
    if (!modal) return;

    let currentStep = 1;
    const totalSteps = 3;

    const nextBtn = document.getElementById('onboardingNext') as HTMLButtonElement | null;
    const skipBtn = document.getElementById('skipOnboarding') as HTMLButtonElement | null;
    const dots = document.querySelectorAll('.dot');

    function showStep(step: number) {
        // Hide all steps
        const steps = document.querySelectorAll('.onboarding-step') as NodeListOf<HTMLElement>;
        steps.forEach((s) => {
            s.style.display = 'none';
        });

        // Show current step
        const currentStepEl = document.querySelector(`[data-step="${step}"]`) as HTMLElement | null;
        if (currentStepEl) {
            currentStepEl.style.display = 'block';
            // Trigger animation by removing and re-adding animation class
            currentStepEl.style.animation = 'none';
            setTimeout(() => {
                currentStepEl.style.animation = 'stepFadeIn 0.4s ease-out';
            }, 10);
        }

        // Update dots
        dots.forEach((dot, index) => {
            if (index + 1 === step) {
                dot.classList.add('active');
            } else {
                dot.classList.remove('active');
            }
        });

        // Update button text
        if (nextBtn) {
            nextBtn.textContent = step === totalSteps ? 'Get Started' : 'Next';
        }
    }

    function closeOnboarding() {
        if (modal) {
            modal.style.display = 'none';
        }
        chrome.storage.local.set({ [ONBOARDING_COMPLETED_KEY]: true });
        tbEvent('onboarding.completed', { completedStep: currentStep });
    }

    // Next button handler
    nextBtn?.addEventListener('click', () => {
        if (currentStep < totalSteps) {
            currentStep++;
            showStep(currentStep);
            tbEvent('onboarding.step_viewed', { step: currentStep });
        } else {
            // Last step - close onboarding
            closeOnboarding();
        }
    });

    // Skip button handler
    skipBtn?.addEventListener('click', () => {
        closeOnboarding();
        tbEvent('onboarding.skipped', { skippedAtStep: currentStep });
    });

    // Dot click handlers
    dots.forEach((dot, index) => {
        dot.addEventListener('click', () => {
            currentStep = index + 1;
            showStep(currentStep);
            tbEvent('onboarding.step_viewed', { step: currentStep });
        });
    });

    // Initialize first step
    showStep(1);
}

async function maybeShowOnboarding() {
    const modal = document.getElementById('onboardingModal') as HTMLElement | null;
    if (!modal) return;

    const canShow = await shouldShowOnboarding();
    if (!canShow) return;

    modal.style.display = 'flex';

    try {
        tbEvent('onboarding.shown');
    } catch (e) {
        console.error('Failed to track onboarding show', e);
    }
}

function startMultiPagePopupTimer(isMultiPage: boolean) {
    if (!isMultiPage) return;
    // Clear any existing timer
    if (multiPagePopupTimeout !== null) {
        clearTimeout(multiPagePopupTimeout);
        multiPagePopupTimeout = null;
    }
    multiPagePopupTimeout = window.setTimeout(async () => {
        const button = document.getElementById('Download') as HTMLButtonElement | null;
        const stillDownloading = button?.getAttribute('data-downloading') === 'true';
        if (stillDownloading) {
            await maybeShowRatingModal();
        }
    }, 5000);
}

function clearMultiPagePopupTimer() {
    if (multiPagePopupTimeout !== null) {
        clearTimeout(multiPagePopupTimeout);
        multiPagePopupTimeout = null;
    }
}

class InfoMessage {
    private infoPanel!: HTMLElement;
    private infoText!: HTMLElement;
    private cancelLink!: HTMLElement;
    private shouldClearAfterDownload: boolean = false;
    private static instance: InfoMessage | null = null;

    private constructor() {
        // Private constructor to prevent direct instantiation
    }

    private initialize() {
        this.infoPanel = document.getElementById("infoPanel") as HTMLElement;
        this.infoText = document.getElementById("infoText") as HTMLElement;
        this.cancelLink = document.getElementById("cancel-link") as HTMLElement;
    }

    static getInstance(): InfoMessage {
        if (!InfoMessage.instance) {
            InfoMessage.instance = new InfoMessage();
        }
        return InfoMessage.instance;
    }

    setMessage(message: string, clearAfterDownload: boolean, showCancelLink: boolean = false) {
        this.infoText.innerHTML = message;
        this.infoPanel.style.visibility = "visible";
        this.cancelLink.style.visibility = showCancelLink ? "visible" : "hidden";
        this.shouldClearAfterDownload = clearAfterDownload;
    }

    clear() {
        this.infoText.textContent = "";
        this.infoPanel.style.visibility = "hidden";
        this.cancelLink.style.visibility = "hidden";
        this.shouldClearAfterDownload = false;
    }

    shouldClearOnDownloadComplete(): boolean {
        return this.shouldClearAfterDownload;
    }
}

