// Port connection to background for cleanup on sidepanel close
let backgroundPort: chrome.runtime.Port | null = null;

function initializeBackgroundPort() {
    backgroundPort = chrome.runtime.connect({ name: 'sidepanel' });
    backgroundPort.onDisconnect.addListener(() => {
        console.log('Background port disconnected');
        backgroundPort = null;
    });
}

function notifyTaskStarted(taskId: string) {
    if (backgroundPort) {
        backgroundPort.postMessage({ type: 'setTaskId', taskId });
    }
}

function notifyTaskEnded() {
    if (backgroundPort) {
        backgroundPort.postMessage({ type: 'clearTaskId' });
    }
}

function initializeThankYouMessage() {
    const thankYouMessage = document.getElementById("thankYouMessage") as HTMLElement;

    function showThankYouMessage() {
        thankYouMessage.style.visibility = "visible";

        function createHeart() {
            const heart = document.createElement("span");
            heart.className = "heart-emoji";
            heart.textContent = "❤️";

            // Randomize horizontal position
            heart.style.left = `${Math.random() * 100}%`;
            heart.style.position = "absolute";
            heart.style.bottom = "10px";

            thankYouMessage.appendChild(heart);

            // Remove the heart after animation
            setTimeout(() => {
                heart.remove();
            }, 3000);
        }

        // Start heart animation and stop after 30 seconds
        const heartInterval = setInterval(createHeart, 600);
        setTimeout(() => clearInterval(heartInterval), 30000);
    }

    paywall.on('purchase_completed', (payload) => {
        // Only celebrate a fresh payment, not a restored/already-active subscription.
        if (!payload.restored) {
            showThankYouMessage();
        }
    });
}

