async function executeDownload(isMultiPage: boolean) {
    // Re-entrancy guard. Until the download actually starts (downloadStarted
    // disables the button), the Download button stays enabled — including while
    // the paywall modal is up and during the async startup below. Hold the guard
    // for the whole function so a second click in that window can't open another
    // paywall or start a parallel download.
    if (paywallGatePending) {
        return;
    }
    paywallGatePending = true;
    try {
        // Gate behind the paywall before touching any UI state.
        const allowed = await passPaywall();
        // If the user dismisses the paywall without purchasing, leave the button
        // untouched and bail out.
        if (!allowed) {
            return;
        }
        tbEvent('download.paywall_passed')

        clearInfoMessage();
        highestLoadedPages = 0; // Reset progress tracking for new download
        tbEvent('download.started')
        const tabId = await getTabId();
        const taskId = crypto.randomUUID();
        if (tabId) {
            await downloadStarted(tabId, taskId, isMultiPage);
            // Show initial info message with cancel link immediately
            setInfoMessage("<strong>Do not close the page.</strong><br>Preparing download...", true, true);
        }

        // Start 5s popup trigger if multi-page
        startMultiPagePopupTimer(isMultiPage);

        if (tabId) {
            try {
                await sendMessage('collectHtml', { tabId, taskId, isMultiPage }, tabId);
                tbEvent('download.sent_via_connection')
            } catch (error: any) {
                if (error.message === "Could not establish connection. Receiving end does not exist.") {
                    await askToReloadThePage();
                } else if (error.message === "The page keeping the extension port is moved into back/forward cache, so the message channel is closed.") {
                    await askNotToChangeThePage();
                } else {
                    throw error; // Re-throw error if it's not the target error
                }
            }
        } else {
            await showErrorMessage();
        }
    } finally {
        paywallGatePending = false;
    }
}

// The task id the user explicitly cancelled via the cancel link. The offscreen
// document reports cancellations and genuine failures the same way (runChain
// returns falsy → 'cancel' message), so we track user intent here to tell them
// apart and avoid showing an error / logging a failure for a deliberate cancel.
// Only one download runs at a time (the Download button tracks a single task),
// so a single id suffices — and if a cancel click loses the race to completion
// (no 'cancel' message arrives) the stale id is simply overwritten next time.
let lastUserCancelledTaskId: string | null = null;

async function cancel(taskId: string) {
    setButtonToDownload()
    DownloadTask.dispose(taskId);
    if (taskId === lastUserCancelledTaskId) {
        lastUserCancelledTaskId = null;
        // User-initiated cancellation is not a failure: keep the UI quiet (the
        // cancel-link handler already cleared the message) and don't emit a
        // download.failed event or bump the failure counter.
        clearInfoMessage();
        hideDownloadChip(true);
        return;
    }
    await showErrorMessage();
}

function clearInfoMessage() {
    infoMessage.clear();
}

function setInfoMessage(message: string, clearAfterFinishingDownload: boolean, showCancelLink: boolean = false) {
    infoMessage.setMessage(message, clearAfterFinishingDownload, showCancelLink);
}

async function showErrorMessage() {
    tbEvent('download.failed')
    setInfoMessage("Sorry, something was wrong 💔<br/>Please reload the page.", false, false)
    setButtonToDownload()
    hideDownloadChip(true)
    hideShowInFolder();
    await incrementStorageCounter(FAILED_DOWNLOADS_KEY)
}

// Track the highest loaded pages count to ignore out-of-order messages
let highestLoadedPages = 0;

async function showInfoMessage(progress: { loadedPages: number; discoveredPages: number; allPagesDiscovered: boolean }) {
    // Ignore out-of-order messages
    if (progress.loadedPages < highestLoadedPages) {
        return;
    }
    highestLoadedPages = progress.loadedPages;

    let message = "<strong>Do not close the page.</strong><br>";
    message += "Loaded " + progress.loadedPages + " pages<br>";
    if (progress.allPagesDiscovered) {
        message += "Discovered " + progress.discoveredPages + " pages";
    } else {
        message += "Discovered " + progress.discoveredPages + " pages so far...";
    }
    setInfoMessage(message, true, true); // Show cancel link for info messages
}

