async function downloadPreparedData(info: { downloadableInfo: DownloadableInfo | undefined, url: string }) {
    const fobj = info.downloadableInfo?.options;
    const url = info.url
    if (fobj !== undefined) {
        await initiateDownload({info: fobj, url})
        tbEvent('download.success', {
            isMultiPage: info.downloadableInfo?.isMultiPage,
            maxDepth: info.downloadableInfo?.maxDepth,
            url: url,
        })
    } else {
        tbEvent('download.object_missing', {
            isMultiPage: info.downloadableInfo?.isMultiPage,
            maxDepth: info.downloadableInfo?.maxDepth,
            url: url,
        })
    }
    if (info.downloadableInfo) {
        if (info.downloadableInfo.isMultiPage) {
            tbEvent('download.multi_page', {
                maxDepth: info.downloadableInfo.maxDepth,
                url: url,
            })
        } else {
            tbEvent('download.single_page')
        }
    }
    if (info.downloadableInfo?.quotaExceeded) {
        infoMessage.setMessage("This website is too large to save completely.<br>Download incomplete - some pages could not be saved.", false, false)
    } else if (info.downloadableInfo?.someLinksNotDownloaded) {
        infoMessage.setMessage("Some links were not downloaded because they redirected to other sites.", false, false)
    }
    setButtonToDownload();

    // Mark visual chip success and schedule hide
    markDownloadChipSuccess();

    if (infoMessage.shouldClearOnDownloadComplete()) {
        clearInfoMessage();
    }

    // Clear any multi-page popup timer once we have prepared data
    clearMultiPagePopupTimer();

    // Show rating UI after a short delay
    setTimeout(async () => {
        // If modal will show, don't show the post-download rating container
        const willShowModal = await shouldShowRatingPopup();
        if (willShowModal) {
            void maybeShowRatingModal();
        } else {
            let ratingContainer = document.getElementById("ratingContainer") as HTMLElement;
            ratingContainer.style.visibility = "visible";
            tbEvent('rating.shown', { source: 'post_download' });
        }
    }, 2000);
}

async function initiateDownload(result: { info: DownloadOptions, url: string }) {
    console.log("Panel: Download data ready, initiate downloading...");
    const fobj = result.info;
    chrome.downloads.download(fobj, (res) => {
        lastDownloadId = res;
        chrome.downloads.onChanged.addListener(async function listener(delta) {
            await capturing(sentry_scope, "downloads_onChanged_listener", undefined, async () => {
                if (delta.id === res && delta.state && delta.state.current === 'complete') {
                    const version = chrome.runtime.getManifest().version

                    tbEvent('download.complete', {
                        version: version,
                    })

                    await incrementStorageCounter(SUCCESS_DOWNLOADS_KEY)

                    chrome.downloads.onChanged.removeListener(listener)
                }
            });
        })
    });
}

async function downloadStarted(tabId: number, taskId: string, isMultiPage: boolean) {
    // Notify background about active task for cleanup on sidepanel close
    notifyTaskStarted(taskId);

    let button = document.getElementById("Download") as HTMLButtonElement;
    button.textContent = "Downloading..."
    button.disabled = true;
    button.setAttribute('data-downloading', 'true');
    button.setAttribute('data-downloading-tab-id', tabId.toString());
    button.setAttribute('data-downloading-task-id', taskId);
    
    // Loading bar removed

    // Show chip
    showDownloadChip();

    // Hide rating prompt while a new download is in progress
    const ratingContainer = document.getElementById("ratingContainer") as HTMLElement | null;
    if (ratingContainer) {
        ratingContainer.style.visibility = "hidden";
    }

    // Show loader animation only for multi-page mode
    if (isMultiPage) {
        showLoader();
    }

    // Reset last download data and hide link for new download
    lastDownloadId = null;
    hideShowInFolder();

    // Hide button (keep layout) only for multi-page mode
    if (isMultiPage) {
        button.style.visibility = 'hidden';
    } else {
        button.style.visibility = 'visible';
    }
}

