// Periodically check if the extension is pinned
async function monitorPinState() {
    const pinTip = document.getElementById("pin-tip") as HTMLElement;
    let isCurrentlyVisible = false;

    setInterval(async () => {
        await capturing(sentry_scope, "monitor_pin_state_interval", undefined, async () => {
            let userSettings = await chrome.action.getUserSettings();
            const shouldBeVisible = !userSettings.isOnToolbar;

            if (shouldBeVisible && !isCurrentlyVisible) {
                // Show the tip with smooth animation
                pinTip.style.display = "block";
                pinTip.classList.remove("fade-out");
                pinTip.classList.add("fade-in");
                isCurrentlyVisible = true;
            } else if (!shouldBeVisible && isCurrentlyVisible) {
                // Hide the tip with smooth animation
                pinTip.classList.remove("fade-in");
                pinTip.classList.add("fade-out");
                isCurrentlyVisible = false;
                
                // Hide the element after animation completes
                setTimeout(() => {
                    if (!isCurrentlyVisible) { // Only hide if still should be hidden
                        pinTip.style.display = "none";
                    }
                }, 300); // Match animation duration
            }
        });
    }, 500); // Check every 0.5 seconds
}

