// --- Download chip UI helpers ---
function getChip(): HTMLElement | null {
    return document.getElementById('downloadChip') as HTMLElement | null;
}

// --- Lottie loader helpers ---
function ensureLottie(): void {
    const wrapper = document.getElementById('lottieLoader') as HTMLElement | null;
    const container = document.getElementById('lottieContainer') as HTMLElement | null;
    if (!wrapper || !container) return;
    if (!lottieInstance) {
        const path = chrome.runtime.getURL('Loading.json');
        lottieInstance = lottie.loadAnimation({
            container,
            renderer: 'svg',
            loop: true,
            autoplay: true,
            path,
            rendererSettings: { preserveAspectRatio: 'xMidYMid meet' }
        });
    }
}

function showLoader(): void {
    const wrapper = document.getElementById('lottieLoader') as HTMLElement | null;
    if (!wrapper) return;
    ensureLottie();
    wrapper.style.display = 'flex';
    wrapper.setAttribute('aria-busy', 'true');
    try { (lottieInstance as any)?.play?.(); } catch (_) { }
}

function hideLoader(): void {
    const wrapper = document.getElementById('lottieLoader') as HTMLElement | null;
    if (!wrapper) return;
    wrapper.style.display = 'none';
    wrapper.setAttribute('aria-busy', 'false');
    try { (lottieInstance as any)?.stop?.(); } catch (_) { }
}

// --- Download actions (show in folder) ---
function initializeShowInFolder() {
    const link = document.getElementById('showInFolderLink') as HTMLAnchorElement | null;
    if (!link) return;
    // Set OS-specific label
    const platform = (navigator as any).userAgentData && (navigator as any).userAgentData.platform
        ? ((navigator as any).userAgentData.platform as string).toLowerCase()
        : navigator.platform.toLowerCase();
    const isMac = platform.includes('mac') || platform.includes('darwin');
    const isWindows = platform.includes('win');
    const isLinux = platform.includes('linux');
    const appName = isMac ? 'Finder' : isWindows ? 'File Explorer' : isLinux ? 'File Manager' : 'File Manager';
    link.textContent = `Show in ${appName}`;
    link.setAttribute('href', 'javascript:void(0)');
    link.addEventListener('click', (e) => {
        e.preventDefault();
        if (lastDownloadId !== null) {
            try {
                chrome.downloads.show(lastDownloadId);
            } catch (e) {
                console.error(e);
            }
        }
    });
}

function showShowInFolder() {
    const actions = document.getElementById('downloadActions') as HTMLElement | null;
    if (actions) actions.style.visibility = 'visible';
}

function hideShowInFolder() {
    const actions = document.getElementById('downloadActions') as HTMLElement | null;
    if (actions) actions.style.visibility = 'hidden';
}

// (Removed duplicate implementations)

function showDownloadChip(): void {
    const chip = getChip();
    if (!chip) return;
    if (chipHideTimeout !== null) {
        clearTimeout(chipHideTimeout);
        chipHideTimeout = null;
    }
    // Reset state
    chip.classList.remove('success');
    const text = chip.querySelector('.chip-text') as HTMLElement | null;
    if (text) text.textContent = 'Downloading in progress...';
    chip.classList.add('show');
}

function markDownloadChipSuccess(): void {
    const chip = getChip();
    if (!chip) return;
    const text = chip.querySelector('.chip-text') as HTMLElement | null;
    if (text) text.textContent = 'Download complete';
    chip.classList.add('show', 'success');
    showShowInFolder();

    // Auto-hide after a short delay for a pleasant dwell time
    if (chipHideTimeout !== null) {
        clearTimeout(chipHideTimeout);
    }
    chipHideTimeout = window.setTimeout(() => {
        hideDownloadChip(false);
    }, 1800);
}

function hideDownloadChip(immediate: boolean): void {
    const chip = getChip();
    if (!chip) return;
    if (chipHideTimeout !== null) {
        clearTimeout(chipHideTimeout);
        chipHideTimeout = null;
    }
    if (immediate) {
        chip.classList.remove('success', 'show');
        const text = chip.querySelector('.chip-text') as HTMLElement | null;
        if (text) text.textContent = 'Downloading in progress...';
        return;
    }
    // remove show to fade out, then cleanup
    chip.classList.remove('show');
    // Match CSS transition (~220ms), add buffer for safety
    window.setTimeout(() => {
        chip.classList.remove('success');
    }, 260);
}

async function getTabId(): Promise<number | undefined> {
    const tabs = await chrome.tabs.query({active: true, currentWindow: true});
    return (tabs.length > 0) ? tabs[0].id : undefined;
}

async function initializeWarningSystem(sentry_scope: any) {
    // Map of blocked video streaming platforms with their display names
    const blockedVideoStreamingPlatforms: { [key: string]: string } = {
        'youtube.com': 'YouTube',
        'netflix.com': 'Netflix',
        'hulu.com': 'Hulu',
        'disneyplus.com': 'Disney+',
        'primevideo.com': 'Prime Video',
        'hbomax.com': 'HBO Max',
        'max.com': 'Max',
        'peacocktv.com': 'Peacock',
        'paramountplus.com': 'Paramount+',
        'tv.apple.com': 'Apple TV',
        'twitch.tv': 'Twitch',
        'crunchyroll.com': 'Crunchyroll'
    };

    function getBlockedPlatformName(url: string): string | null {
        for (const [domain, name] of Object.entries(blockedVideoStreamingPlatforms)) {
            if (url.includes(domain)) {
                return name;
            }
        }
        return null;
    }

    function updateWarningText(url: string | undefined): void {
        const warningContainer = document.getElementById("warningContainer") as HTMLElement;
        const warningText = document.getElementById("warningText") as HTMLElement;
        const downloadButton = document.getElementById("Download") as HTMLButtonElement;
        
        // If download is in progress, don't modify the button state
        if (downloadButton.getAttribute('data-downloading') === 'true') {
            return;
        }

        if (url === undefined || url === "chrome://newtab/" || url === "" || url === "about:blank") {
            warningText.textContent = "";
            warningContainer.style.visibility = "hidden";
            downloadButton.disabled = true;
        } else {
            const blockedPlatform = getBlockedPlatformName(url);
            if (blockedPlatform) {
                warningText.textContent = `Sorry, I can't download from ${blockedPlatform} 😢`;
                warningContainer.style.visibility = "visible";
                downloadButton.disabled = true;
            } else if (url.startsWith("chrome://") && url !== "chrome://newtab/") {
                warningText.textContent = "Sorry, can't download from 'chrome://' 😢";
                warningContainer.style.visibility = "visible";
                downloadButton.disabled = true;
            } else if (url.includes("chromewebstore.google.com")) {
                warningText.textContent = "Sorry, I can't download from Chrome Web Store 😢";
                warningContainer.style.visibility = "visible";
                downloadButton.disabled = true;
            } else {
                warningText.textContent = "";
                warningContainer.style.visibility = "hidden";
                downloadButton.disabled = false;
            }
        }
    }

    // Check the initial active tab URL
    const [tab] = await chrome.tabs.query({ active: true, lastFocusedWindow: true });
    if (tab && tab.url) updateWarningText(tab.url);

    // Listen for tab activation
    chrome.tabs.onActivated.addListener(async (activeInfo) => {
        await capturing(sentry_scope, "tabs_onActivated_listener", undefined, async () => {
            const tab = await chrome.tabs.get(activeInfo.tabId);
            if (tab.active) {
                updateWarningText(tab.url);
            }
        });
    });

    // Listen for tab updates
    chrome.tabs.onUpdated.addListener(async (tabId, changeInfo, tab) => {
        await capturing(sentry_scope, "tabs_onUpdated_listener", undefined, async () => {
            if (tab.active) {
                updateWarningText(tab.url);
            }
        });
    });
}

