// Initialize reload banner functionality
async function initializeReloadBanner() {
    const reloadBanner = document.getElementById('reloadBanner') as HTMLElement;
    const reloadButton = document.getElementById('reloadButton') as HTMLButtonElement;

    if (!reloadBanner || !reloadButton) return;

    const FAILED_INJECTION_TABS_KEY = 'failedInjectionTabs';

    // Function to check and update banner visibility
    const updateBannerVisibility = async () => {
        console.log('[RELOAD BANNER] Checking banner visibility...');
        const [tab] = await chrome.tabs.query({ active: true, lastFocusedWindow: true });
        console.log('[RELOAD BANNER] Current tab:', tab?.id, tab?.url);

        if (!tab?.id) {
            console.log('[RELOAD BANNER] No active tab, hiding banner');
            reloadBanner.style.display = 'none';
            return;
        }

        const result = await chrome.storage.local.get([FAILED_INJECTION_TABS_KEY]);
        const failedTabs = result[FAILED_INJECTION_TABS_KEY] || {};
        console.log('[RELOAD BANNER] Failed tabs in storage:', failedTabs);
        console.log('[RELOAD BANNER] Is current tab in failed list?', tab.id in failedTabs);

        if (tab.id in failedTabs) {
            console.log('[RELOAD BANNER] Showing banner for tab', tab.id);
            reloadBanner.style.display = 'block';
        } else {
            console.log('[RELOAD BANNER] Hiding banner for tab', tab.id);
            reloadBanner.style.display = 'none';
        }
    };

    // Check on initial load
    await updateBannerVisibility();

    // Handle reload button click
    reloadButton.addEventListener('click', async () => {
        const [tab] = await chrome.tabs.query({ active: true, lastFocusedWindow: true });
        if (tab?.id) {
            // Immediately remove from failed list to prevent blinking
            const result = await chrome.storage.local.get([FAILED_INJECTION_TABS_KEY]);
            const failedTabs = result[FAILED_INJECTION_TABS_KEY] || {};
            delete failedTabs[tab.id];
            await chrome.storage.local.set({ [FAILED_INJECTION_TABS_KEY]: failedTabs });
            console.log('[RELOAD BANNER] Removed tab from failed list before reload:', tab.id);
        }

        reloadBanner.style.display = 'none';
        await sendMessage('reloadCurrentTab', undefined);
    });

    // Check when tab changes
    chrome.tabs.onActivated.addListener(async () => {
        await updateBannerVisibility();
    });

    // Check when tab updates (e.g., navigation, reload)
    chrome.tabs.onUpdated.addListener(async (tabId, changeInfo, tab) => {
        if (tab.active) {
            await updateBannerVisibility();
        }
    });

    // Listen for storage changes (when background updates the failed tabs list)
    chrome.storage.onChanged.addListener((changes, areaName) => {
        if (areaName === 'local' && changes[FAILED_INJECTION_TABS_KEY]) {
            updateBannerVisibility();
        }
    });
}
